/**
 * Plain-English copy for the deterministic verdict engine (Phase 4.14).
 *
 * This module computes NOTHING and judges NOTHING — it only turns the
 * engine's own structured VerdictLabel/VerdictReason output (lib/calculations/verdict.ts)
 * into the exact wording the Phase 4.14 brief specified, so the Summary UI
 * and PDF render identical language from one place instead of drifting
 * apart. AI copy (Deal Coach) is separate and lives in dealCoachPrompt.ts —
 * nothing here is fed to or generated by the model.
 */
import { formatMetricValue } from "./format";
import { METRIC_VALUE_FORMAT } from "./metricBreakdowns";
import type { VerdictLabel, VerdictReason, VerdictUnavailableReason } from "../calculations/verdict";

