function fmt(r: VerdictReason, currency: string): string {
  if (r.value === null || r.value === undefined) return "";
  const format = r.metric ? METRIC_VALUE_FORMAT[r.metric] ?? "number" : "number";
  return formatMetricValue(r.value, format, currency);
}

/** Formats one structured VerdictReason into a plain-English sentence — the single source both the Summary UI and the PDF read from. */
export function formatVerdictReason(reason: VerdictReason, currency = "R"): string {
  const template = REASON_TEMPLATES[reason.code];
  if (template) return template(reason, currency);
  return reason.code.replace(/_/g, " ");
}
